[{"order":1,"type":"heading","text":"Mastering Custom Refs with customRef in Vue.js"},{"order":2,"type":"paragraph","text":"Vue 3 provides a powerful Composition API utility called customRef, which allows explicit control over the dependency tracking and trigger updates associated with a ref. This is particularly useful for advanced use cases such as debouncing input, local storage synchronization, or creating rate-limited reactive properties."},{"order":3,"type":"subheading","text":"Understanding the customRef Factory Function"},{"order":4,"type":"paragraph","text":"The customRef function accepts a factory function as its argument. This factory receives two callbacks: track and trigger. These functions give you direct access to Vue's reactivity system."},{"order":5,"type":"bullet_point","text":"track: Called inside the getter to explicitly notify Vue that this property should be tracked as a dependency."},{"order":6,"type":"bullet_point","text":"trigger: Called inside the setter to explicitly notify Vue that the value has changed and components should re-render."},{"order":7,"type":"subheading","text":"Practical Example: Creating a Debounced Ref"},{"order":8,"type":"paragraph","text":"A common use case for customRef is debouncing input values to prevent excessive API requests or expensive computations while a user is typing."},{"order":9,"type":"code","text":"import { customRef } from 'vue';

function useDebouncedRef(value, delay = 200) {
  let timeout;
  return customRef((track, trigger) => {
    return {
      get() {
        track();
        return value;
      },
      set(newValue) {
        clearTimeout(timeout);
        timeout = setTimeout(() => {
          value = newValue;
          trigger();
        }, delay);
      }
    };
  });
}"},{"order":10,"type":"subheading","text":"Using the Debounced Ref in a Component"},{"order":11,"type":"paragraph","text":"Now you can import and use your custom ref just like a standard ref created with the ref() function."},{"order":12,"type":"code","text":"<template>
  <div>
    <input v-model="text" placeholder="Type something..." />
    <p>Debounced value: {{ text }}</p>
  </div>
</template>

<script setup>
import { useDebouncedRef } from './useDebouncedRef';

const text = useDebouncedRef('', 500);
</script>"},{"order":13,"type":"subheading","text":"Best Practices and Conclusion"},{"order":14,"type":"bullet_point","text":"Always call track() in the getter to ensure reactivity dependencies are correctly registered."},{"order":15,"type":"bullet_point","text":"Always call trigger() in the setter when the underlying value actually changes to update the UI."},{"order":16,"type":"paragraph","text":"By leveraging customRef, you unlock fine-grained control over Vue 3 state management, empowering you to write cleaner and more performant composables."}]
